from hx import *
import logic_tools as L
from logic_tools import V,N,A,O,I,E,X
p,q,r=V('p'),V('q'),V('r')
def TT(f):
    vs,rows=L.table(f)
    return table(vs+[L.show(f)],[[('Đ' if x else 'S') for x in vals]+[('Đ' if res else 'S')] for vals,res in rows])
def TT2(cols,vs=('p','q')):
    import itertools
    head=list(vs)+[L.show(c) for c in cols]; rows=[]
    for vals in itertools.product([True,False],repeat=len(vs)):
        env=dict(zip(vs,vals)); rows.append([('Đ' if v else 'S') for v in vals]+[('Đ' if L.ev(c,env) else 'S') for c in cols])
    return table(head,rows)
def module():
    parts=[]
    # ---------------- PHẦN 1
    s=[]
    s.append(sl(f'<p>Logic mệnh đề là <b>ngôn ngữ chính xác</b> để phát biểu và chứng minh, đồng thời là nền của điều kiện <code>if</code>, mạch số và truy vấn dữ liệu. Câu 1a của MỌI đề thi Toán rời rạc 1 PTIT (2017–2024) đều rơi vào đây.</p>'+ul(['Nhận biết mệnh đề và giá trị chân lý','Sáu phép nối ¬ ∧ ∨ ⊕ ⇒ ⇔ và bảng chân trị','Tương đương logic, hằng đúng, mâu thuẫn','Quy tắc suy diễn và dạng chuẩn tắc']),'MODULE 1 · Giáo trình 2016 §1.2 · Đề cương 1.1','Logic mệnh đề',
        explain='Bạn có thể xem "mệnh đề" như một công tắc chỉ có hai vị trí Đúng hoặc Sai. Toàn bộ chương này học cách nối nhiều công tắc lại với nhau và tính xem công tắc cuối cùng bật hay tắt.'))
    s.append(sl('<p><b>Mệnh đề</b> là câu khẳng định có giá trị chân lý xác định: hoặc Đúng (Đ, T, 1) hoặc Sai (S, F, 0), không thể cả hai.</p>'+table(['Là mệnh đề','Không phải mệnh đề'],[['Hà Nội là thủ đề của Việt Nam (Đ)'.replace('thủ đề','thủ đô'),'Bây giờ là mấy giờ? (câu hỏi)'],['1 + 1 = 3 (S)','Hãy đóng cửa lại! (mệnh lệnh)'],['Mọi số chẵn đều chia hết cho 2 (Đ)','x + 2 = 5 (phụ thuộc x: là <i>vị từ</i>)'],['Có vô hạn số nguyên tố (Đ)','Bài này khó quá! (cảm thán)']])+callout('warn','Lưu ý','Mệnh đề SAI như "1 + 1 = 3" vẫn là mệnh đề. Câu như "x + 2 = 5" chỉ thành mệnh đề khi gán giá trị cho x hoặc lượng hóa (Module 2).'),'PHẦN 1 · Nền tảng','Mệnh đề và giá trị chân lý',
        explain='Hỏi: câu này có thể nói "đúng" hoặc "sai" một cách dứt khoát không? Có thì là mệnh đề. Câu hỏi, câu lệnh, cảm xúc thì không.'))
    tbl=table(['p','q','¬p','p ∧ q','p ∨ q','p ⊕ q','p ⇒ q','p ⇔ q'],[['Đ','Đ','S','Đ','Đ','S','Đ','Đ'],['Đ','S','S','S','Đ','Đ','S','S'],['S','Đ','Đ','S','Đ','Đ','Đ','S'],['S','S','Đ','S','S','S','Đ','Đ']])
    s.append(sl(tbl+'<ul><li><b>∧</b> (và): đúng khi cả hai đúng.</li><li><b>∨</b> (hoặc, bao hàm): sai khi cả hai sai.</li><li><b>⊕</b> (hoặc loại trừ): đúng khi hai vế KHÁC nhau.</li><li><b>⇒</b>: chỉ sai khi p Đ và q S.</li><li><b>⇔</b>: đúng khi hai vế CÙNG giá trị.</li></ul>','PHẦN 1 · Nền tảng','Bảng chân trị của các phép nối',
        explain='Học thuộc dòng "Đ S" của p ⇒ q: đây là dòng duy nhất cho kết quả Sai. Nếu p sai thì mệnh đề "nếu p thì q" luôn coi như đúng (không có gì để vi phạm lời hứa).'))
    s.append(sl(callout('info','Cách đọc p ⇒ q','“Nếu p thì q”; “p kéo theo q”; “p chỉ khi q”; “p là điều kiện <b>đủ</b> của q”; “q là điều kiện <b>cần</b> của p”; “q nếu p”; “q khi p”.')+
        table(['Từ mệnh đề P ⇒ Q','Ký hiệu','Tương đương với P ⇒ Q?'],[['Đảo','Q ⇒ P','Không'],['Phản đảo','¬Q ⇒ ¬P','<b>Có (luôn)</b>'],['Nghịch','¬P ⇒ ¬Q','Không (tương đương đảo)'],['Phủ định','¬(P ⇒ Q) ≡ P ∧ ¬Q','Đối lập']])+
        formula('Chuyển kéo theo về hoặc','P ⇒ Q ≡ ¬P ∨ Q',[('P, Q','hai mệnh đề bất kỳ'),('≡','tương đương logic: cùng bảng chân trị')]),'PHẦN 1 · Nền tảng','Mệnh đề kéo theo và các biến thể',
        explain='Ví dụ: "Nếu trời mưa thì đường ướt". Phản đảo: "Nếu đường không ướt thì trời không mưa" luôn cùng đúng sai với câu gốc. Đảo: "Nếu đường ướt thì trời mưa" có thể sai (đường ướt do xe tưới nước).'))
    parts.append(dict(title='Nền tảng: mệnh đề và các phép nối',bullets=['Mệnh đề, giá trị chân lý','Sáu phép nối và bảng chân trị','Kéo theo, đảo, phản đảo, nghịch'],slides=s))
    # ---------------- PHẦN 2
    s=[]
