    s.append(sl('<h3>Hai cách chứng minh tương đương / hằng đúng</h3>'+table(['','Bảng chân trị','Biến đổi tương đương'],[['Ưu điểm','Máy móc, chắc chắn, ít cần sáng tạo','Ngắn gọn với nhiều biến'],['Nhược điểm','2ⁿ dòng: n = 4 đã 16 dòng','Cần nhớ luật, dễ sai bước'],['Khi nào dùng','n ≤ 3 hoặc đề yêu cầu bằng bảng','n ≥ 4 hoặc đề yêu cầu "dùng các phép biến đổi"']])+callout('good','Mẹo thi','Đề thi PTIT chỉ rõ cách: “dùng bảng chân lý” (2023-24) hoặc “dùng các phép biến đổi tương đương” (2017-2020). Làm ĐÚNG cách đề yêu cầu, và với biến đổi hãy ghi tên luật ở mỗi bước.'),'PHẦN 2 · Phương pháp','Chọn phương pháp chứng minh'))
    s.append(sl('<ul><li><b>Hằng đúng</b> (tautology): luôn Đ, ví dụ p ∨ ¬p.</li><li><b>Mâu thuẫn</b> (hằng sai): luôn S, ví dụ p ∧ ¬p.</li><li><b>Thỏa được</b>: có ít nhất một dòng Đ.</li></ul>'+callout('info','Số dòng của bảng','Công thức có n biến có 2ⁿ dòng. Có 2^(2ⁿ) hàm chân trị khác nhau theo n biến (n = 2: 16 hàm).')+TT(I(A(p,I(p,q)),q))+'<p>Công thức <i>[p ∧ (p ⇒ q)] ⇒ q</i> là hằng đúng (modus ponens).</p>','PHẦN 2 · Phương pháp','Hằng đúng, mâu thuẫn, thỏa được'))
    s.append(sl(table(['Quy tắc','Tiền đề','Kết luận'],[['Modus ponens','p ⇒ q ; p','q'],['Modus tollens','p ⇒ q ; ¬q','¬p'],['Tam đoạn luận giả định','p ⇒ q ; q ⇒ r','p ⇒ r'],['Tam đoạn luận tuyển','p ∨ q ; ¬p','q'],['Hợp','p ; q','p ∧ q'],['Cộng','p','p ∨ q'],['Rút gọn','p ∧ q','p'],['Phân giải','p ∨ q ; ¬p ∨ r','q ∨ r']])+callout('bad','Hai ngụy biện hay gặp','Khẳng định hậu kiện: (p ⇒ q, q) ⊢ p là SAI. Phủ định tiền kiện: (p ⇒ q, ¬p) ⊢ ¬q là SAI.'),'PHẦN 2 · Phương pháp','Quy tắc suy diễn'))
    s.append(sl('<p>Mọi công thức đều tương đương một <b>dạng tuyển chuẩn (DNF)</b> — tuyển của các hội — và một <b>dạng hội chuẩn (CNF)</b> — hội của các tuyển.</p>'+formula('Cách lập DNF từ bảng chân trị','DNF = ⋁ (hội các literal của mỗi dòng có giá trị Đ)',[('dòng Đ','mỗi dòng Đ cho một hạng tử: biến Đ giữ nguyên, biến S lấy phủ định')])+f'<p>Ví dụ p ⇒ q có 3 dòng Đ: (p,q) = (Đ,Đ), (S,Đ), (S,S) nên p ⇒ q ≡ (p ∧ q) ∨ (¬p ∧ q) ∨ (¬p ∧ ¬q).</p>','PHẦN 2 · Phương pháp','Dạng chuẩn tắc (giáo trình 1.2.3)'))
    parts.append(dict(title='Phương pháp: luật, bảng chân trị, suy diễn',bullets=['Các luật tương đương','Chọn phương pháp chứng minh','Quy tắc suy diễn, dạng chuẩn tắc'],slides=s))
